# Databricks notebook source
# Job step: mode=land (day 30) | checks (retention, reconciliation, governance, D-0427 thread, Lakebase/Genie/app)
# -> evidence/*.md on the Volume, exported to the repo. Proof: evidence/run_log.md
import json, sys, time
from databricks.sdk import WorkspaceClient
w, S, V = WorkspaceClient(), "surajb.ubi_telematics", "/Volumes/surajb/ubi_telematics"
A = {k: (dbutils.widgets.text(k, ""), dbutils.widgets.get(k))[1] for k in ["mode", "job_run_id", "http_smoke", "pipeline_id", "app_dir"]}
q = lambda s: [r.asDict() for r in spark.sql(s).collect()]; one = lambda s: q(s)[0]
j = lambda f: json.load(open(f"{V}/ref/{f}.json"))
if A["mode"] == "land":
    for k in ["gps", "events"]:
        for f in dbutils.fs.ls(f"{V}/landing/holdback/{k}"): dbutils.fs.cp(f.path, f"{V}/landing/{k}/{f.name}", True)
    dbutils.notebook.exit("landed")
def md(t, rows):
    k = list(rows[0]); return f"\n## {t}\n| " + " | ".join(k) + " |\n|" + "---|" * len(k) + "\n" + "".join("| " + " | ".join(str(r[c]) for c in k) + " |\n" for r in rows)
dbutils.fs.mkdirs(f"{V}/ref/evidence")
def out(f, title, body): open(f"{V}/ref/evidence/{f}.md", "w").write(f"# {title} (generated by src/run_checks.py, job run {A['job_run_id']})\n{body}")

# COMMAND ----------
C = "drop_ts < current_timestamp() - INTERVAL 90 DAYS"  # 90-day retention; DML only if rows expired (streams stay append-only)
ret = {t: spark.table(f"{S}.{t}").where(C).count() for t in ["bronze_gps", "bronze_events", "silver_gps_matched", "silver_gps_quarantine"]}
[spark.sql(f"DELETE FROM {S}.{t} WHERE {C}") for t, n in ret.items() if n]
run = w.jobs.get_run(int(A["job_run_id"])); t0 = run.start_time
tasks = [dict(task=t.task_key, attempt=t.attempt_number, result=t.state.result_state.value if t.end_time else "RUNNING (writes this log)",
  secs=round(((t.end_time or time.time() * 1000) - t.start_time) / 1000)) for t in run.tasks]
T = ["bronze_gps", "silver_gps_matched", "silver_gps_quarantine", "silver_trips", "silver_events", "gold_driver_features", "gold_driver_scores"]
dq = one(f"""SELECT count(*) bronze, count(DISTINCT device_id, ts) valid, count_if(_corrupt IS NOT NULL) malformed, round(avg(int(date_trunc('HOUR', ts)
  != drop_ts)) FILTER (WHERE _corrupt IS NULL AND device_id NOT IN (SELECT device_id FROM {S}.silver_device_skew WHERE skewed)) * 100, 3) late_pct,
  (SELECT count_if(skewed) FROM {S}.silver_device_skew) skewed, count(DISTINCT xxhash64(device_id, ts, _corrupt)) FILTER (WHERE _corrupt IS NOT NULL) md
  FROM {S}.bronze_gps"""); md_ = dq.pop("md")
dq["dup_pct"] = round((dq["bronze"] - dq["malformed"]) / dq["valid"] * 100 - 100, 3)
ex = q(f"""SELECT replace(origin.flow_name, '{S}.', '') flow, e.name expectation, sum(e.failed_records) failed FROM event_log('{A["pipeline_id"]}') LATERAL VIEW explode(from_json(details:flow_progress
  .data_quality.expectations, 'array<struct<name:string,failed_records:bigint>>')) x AS e WHERE event_type = 'flow_progress' AND timestamp >= timestamp_millis({t0}) GROUP BY 1, 2 ORDER BY 1, 2""")
n = {r["t"]: r["n"] for r in q(" UNION ALL ".join(f"SELECT '{t}' t, count(*) n FROM {S}.{t}" for t in T))}
rc = dict(bronze=dq["bronze"], matched=n["silver_gps_matched"], quarantine=n["silver_gps_quarantine"], dup_valid=dq["bronze"] - dq["malformed"] - dq["valid"],
  dup_malformed=dq["malformed"] - md_); rc["unexplained"] = 2 * rc["bronze"] - sum(rc.values())
out("run_log", "Run log", md("Tasks (all attempts; retries shown)", tasks) + md("Rows", [dict(t=k, n=v) for k, v in n.items()])
    + md("Defects caught (injected: dup 1.99%, late 3.01%, 266,484 malformed, 5 skewed)", [dq]) + md("Reconciliation: bronze = sum of buckets (dup % is of valid rows)", [rc]) + md("Expectations: failed rows per flow", ex) + md("Retention: expired", [ret]))

# COMMAND ----------
P = f"SELECT lat, lon FROM {S}.silver_gps_matched WHERE device_id = 'TD-0427' AND ts = '2026-10-27 17:44:17'"
F = f"SELECT count(*) drivers, count(DISTINCT state) states FROM {S}.gold_driver_features"; U = f"{S}.underwriter_states SET state = '%s' WHERE user_name = current_user()"
gv, rf = [dict(view="allowlisted", **one(P))], [dict(map="*", **one(F))]
spark.sql(f"DELETE FROM {S}.access_allowlist WHERE user_name = current_user()"); spark.sql("UPDATE " + U % "LA")
try: gv.append(dict(view="not allowlisted", **one(P))); rf.append(dict(map="LA", **one(F)))
finally: spark.sql(f"INSERT INTO {S}.access_allowlist VALUES (current_user(), 'ds')"); spark.sql("UPDATE " + U % "*")
m = j("model_metrics"); lin = q(f"""SELECT DISTINCT replace(source_table_full_name, '{S}.', '') src, replace(target_table_full_name, '{S}.', '') tgt FROM system.access.table_lineage
  WHERE target_table_full_name LIKE '{S}.%' AND source_table_full_name LIKE '{S}.%' AND event_date >= current_date() - 2""")
out("model_and_governance", "Model and governance", "Lift is synthetic by construction; the real test is a pilot parallel run vs the vendor score.\n"
    + md("Model: 5-fold grouped CV, bootstrap 95% CI", [{k: round(m[k], 3) for k in ["gini_base", "gini_tel", "gini_lift", "lift_ci_lo", "lift_ci_hi", "dev_base", "dev_tel"]}])
    + md("Filed relativities by decile", [{f"d{i + 1}": round(r, 3) for i, r in enumerate(m["rel"])}]) + md("GPS mask", gv) + md("State row filter", rf) + md(f"Lineage ({len(lin)} edges)", lin[:5])
    + md("Promotion: train -> @challenger, named approver -> @champion", j("model_promotion")[-3:]) + md("Alias audit (rescore refuses on unmatched)", [j("alias_audit")]))

# COMMAND ----------
sys.path.insert(0, A["app_dir"]); import app_data as D  # in-process smoke: Apps reject job tokens (401)
lb, gb, sid = j("lakebase_bench"), j("genie_bench"), j("genie_space")["space_id"]; pg = lambda s: D.pgq(w, s)[0]
ga = D.genie(w, sid, "Which overrides were approved this week and why?")
sm = [dict(check=k, result=v) for k, v in json.loads(A["http_smoke"] or "{}").items()] + [dict(check="in-process disputes", result=len(D.pgq(w, "SELECT 1 FROM ops.disputes")))]
c = D.pg(w).cursor(); fe = pg("SELECT pg_get_constraintdef(oid) d FROM pg_constraint WHERE conname = 'four_eyes'")["d"].replace(" OR demo", "")
c.execute(f"CREATE TEMP TABLE fe (requested_by text, approved_by text, demo bool, {fe})")  # production four-eyes = live DDL minus the demo clause
try: c.execute("INSERT INTO fe VALUES ('u', 'u', true)"); fe = "ALLOWED"
except D.psycopg2.errors.CheckViolation: fe = "rejected"
c.execute("DROP TABLE fe"); sy = dict(prod_four_eyes_self_approval=fe)
out("lakebase_genie_app", "Lakebase, Genie, app", md("Lakebase: 1,000 lookups + sync check (fails the job on mismatch)", [lb]) + md(f"Genie benchmark {gb['passed']}/{gb['total']}", [dict(q=r["q"][:58],
    result=r["assessment"]) for r in gb["results"]]) + md("App smoke (HTTP from laptop, in-process here)", sm) + md("Production four-eyes", [sy]))
tr = one(f"SELECT trip_id, points, round(distance_mi, 1) mi, speeding_seconds s FROM {S}.silver_trips WHERE trip_id = 'TD-0427-20261027174200'")
raw = one(f"SELECT _ingest_file f, count(*) n FROM {S}.bronze_gps WHERE device_id = 'TD-0427' AND drop_ts = '2026-10-27 17:00' GROUP BY 1")
fe, sc = one(f"SELECT * FROM {S}.gold_driver_features WHERE driver_id = 'D-0427'"), one(f"SELECT * FROM {S}.gold_driver_scores WHERE driver_id = 'D-0427'")
on, ov = pg("SELECT * FROM online.driver_scores_online WHERE driver_id = 'D-0427'"), pg("SELECT * FROM ops.overrides WHERE driver_id = 'D-0427' ORDER BY 1 DESC")
llm = pg("SELECT after->>'recommended_action' a, left(llm_prompt_hash, 12) h FROM ops.audit_log WHERE action = 'llm_draft' ORDER BY id DESC")
J = [("raw file", raw["f"].split("/landing/")[1], f"{raw['n']} rows"), ("bronze", "bronze_gps", one(f"SELECT count(*) n FROM {S}.bronze_gps WHERE device_id = 'TD-0427'")["n"]),
     ("silver", tr["trip_id"], f"{tr['points']} pts, {tr['mi']} mi, {tr['s']} s speeding"), ("gold", "gold_driver_features", f"phone {fe['phone_handling_per_hr']}/h"),
     ("score", f"ubi_risk_score v{sc['model_version']}", f"decile {sc['decile']}, {sc['premium_modifier']}: {'; '.join(sc['reason_codes'])}"),
     ("Lakebase", "driver_scores_online", f"{on['decile']}, {on['premium_modifier']}"), ("dispute", "ops.disputes #1", "passenger had my phone"),
     ("LLM", "audit_log", f"{llm['a']}, prompt {llm['h']}"), ("override", f"#{ov['override_id']}", f"{ov['old_modifier']} -> {ov['new_modifier']} {ov['status']}, demo={ov['demo']}"),
     ("Genie", "UBI Underwriting Analyst", ga["text"][:110].replace("|", "/")), ("lineage", "table_lineage", f"{len(lin)} edges")]
out("journey", "Golden thread: D-0427", md("Layer by layer", [dict(layer=a, object=b, evidence=c) for a, b, c in J]))
